  },
  "license": "MIT",
  "author": "Joel D. Martinez",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/scrylog/scrylog.git",
    "directory": "packages/opencode-plugin"
  },
  "files": [
    "dist",
    "src/diagnostics.ts",
    "README.md",
    "LICENSE"
  ],
  "type": "module",
  "main": "./dist/index.js",
  "module": "./dist/index.js",
  "types": "./dist/index.d.ts",
  "exports": {
    ".": {
      "import": "./dist/index.js",
      "types": "./dist/index.d.ts"
    },
    "./server": {
