    },
    "./package.json": "./package.json"
  },
  "publishConfig": {
    "access": "public"
  },
  "scripts": {
    "build": "tsc",
    "check-types": "tsc --noEmit",
    "clean": "rm -rf .turbo && rm -rf dist",
    "clean:node-modules": "rm -rf node_modules",
    "dev": "tsc --watch",
    "lint": "concurrently --kill-others-on-fail \"bun lint:fmt\" \"bun lint:oxc\" \"bun lint:eslint\" \"bun lint:tsc\"",
    "lint:eslint": "eslint ./src --max-warnings 0",
    "lint:eslint:fix": "bun lint:eslint -- --fix",
    "lint:fix": "bun lint:oxc:fix && bun lint:eslint:fix && bun lint:fmt:fix",
    "lint:fmt": "bun --bun oxfmt --check",
    "lint:fmt:fix": "bun --bun oxfmt",
    "lint:oxc": "oxlint  --tsconfig ./tsconfig.json --deny-warnings",
    "lint:oxc:fix": "bun lint:oxc -- --fix --fix-suggestions",
    "lint:oxc:type-aware": "bun lint:oxc -- --type-aware",
    "lint:oxc:type-check": "bun lint:oxc:type-aware -- --type-check",
    "lint:tsc": "bun tsc --noEmit",
    "lint:tsc:go": "bun tsgo --project ./tsconfig.base.json --noEmit",
    "pack:dry-run": "bash ../../scripts/npm-pack.sh \"$PWD\" \"\" --dry-run",
    "prepack": "npm run build",
    "test": "bun test ./tests --timeout=20000"
  },
  "devDependencies": {
    "@mainqueueio/eslint-config": "0.2.1-next.14",
    "@opencode-ai/plugin": "1.4.0",
    "@opencode-ai/sdk": "1.19.0",
    "@types/node": "^24.3.0",
    "typescript": "6.0.3"
  },
  "peerDependencies": {
    "@opencode-ai/sdk": "*"
  },
  "scrylog": {
    "contractRevision": 2
  }
}

import { suppliedClient, withDispose } from './compatibility';
import { HttpBroker } from './broker';
import { InteractionBridge } from './interactions';
import { OpenCodeInstanceBridge } from './instance';
import { HttpInstanceBroker } from './instance-broker';
import { resolveInteractionCredentials } from './credentials';
import { bridgeJournal } from './bridge-diagnostics';
import { getTmuxPane, getWebhookUrl, post, setTmuxSessionOption, } from './shared';
export const ScrylogServerPlugin = async (input) => {
    const { $, client, directory } = input;
    const webhookUrl = getWebhookUrl();
    let bridge;
    let instanceBridge;
    const credentials = resolveInteractionCredentials({ env: process.env });
    bridgeJournal.record('process.started', {
        operation: 'plugin',
        outcome: credentials.enabled ? 'enabled' : 'disabled',
        reasonCode: credentials.reasonCode,
    });
    if (credentials.reasonCode === 'CONFIG_INVALID_URL') {
        bridgeJournal.record('bridge.cycle', {
            outcome: 'disabled',
            reasonCode: 'CONFIG_INVALID_URL',
        });
    }
    if (credentials.enabled && credentials.bridgeToken) {
        const modern = suppliedClient(client);
        if (modern) {
            try {
                bridge = new InteractionBridge(new HttpBroker(credentials.baseUrl, credentials.bridgeToken, fetch, credentials.apiToken), modern, directory, input.worktree);
                instanceBridge = new OpenCodeInstanceBridge(new HttpInstanceBroker(credentials.baseUrl, credentials.bridgeToken, fetch, credentials.apiToken), modern, directory, input.worktree, {
                    bindSession: (id, signal) => bridge.bindProvisionedSession(id, signal),
                });
                instanceBridge.setObservedSessionSource(() => bridge.observedSessionIds());
                bridge.start();
                instanceBridge.start();
            }
            catch {
                bridgeJournal.record('bridge.cycle', {
                    outcome: 'disabled',
                    reasonCode: 'BRIDGE_INITIALIZATION_FAILED',
                });
                /* Invalid bridge configuration must not affect monitoring. */
            }
        }
        else {
            bridgeJournal.record('bridge.cycle', {
                outcome: 'disabled',
                reasonCode: 'SUPPLIED_CLIENT_UNAVAILABLE',
            });
        }
    }
    if (getTmuxPane()) {
        client.session
            .list()
            .then(({ data }) => {
            if (!data?.length)
                return;
            // eslint-disable-next-line prefer-destructuring
            const latest = [...data]
                .filter((s) => !s.parentID)
                .sort((a, b) => (b.time.updated ?? 0) - (a.time.updated ?? 0))[0];
            if (latest?.id)
                setTmuxSessionOption(latest.id, $);
        })
            .catch(() => { });
    }
    return withDispose({
        event: async ({ event }) => {
            const observed = event;
            if (observed.type === 'server.instance.disposed') {
                await instanceBridge?.dispose();
                await bridge?.dispose();
            }
            else {
                instanceBridge?.event(observed);
                bridge?.event(observed);
            }
            post(webhookUrl, {
                directory,
                event: event.type,
                ...event.properties,
            });
            if (event.type === 'session.created' ||
                event.type === 'session.updated') {
                const sessionID = event.properties.info?.id;
                const parentID = event.properties.info?.parentID;
                if (typeof sessionID === 'string' && !parentID)
                    setTmuxSessionOption(sessionID, $);
            }
        },
    }, async () => {
        await instanceBridge?.dispose();
        await bridge?.dispose();
    });
};
export default ScrylogServerPlugin;
